import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Plane geometry – size will be controlled by parent transform
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Store primitive instances for later cleanup
  const primitiveInstances = [];

  // Apply cinematic primitives if any
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const instance = fn(root, prim.params ?? {});
      primitiveInstances.push(instance);
    }
  }

  // Event handlers container (none for this node)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose material and geometry
    if (material.map && material.map.dispose) material.map.dispose();
    material.dispose();
    geometry.dispose();

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    }

    // Kill any GSAP timelines that might have been created
    if (root.userData._gsapTimelines) {
      for (const tl of root.userData._gsapTimelines) tl.kill();
    }
  };

  // Placeholder for potential GSAP timelines (none required here)
  root.userData._gsapTimelines = [];

  return root;
}
